import {getAction} from '@madou/catalog';
import {createGame,gameStats,transition,allCardInstanceIds,type GameCommand} from '@madou/engine';
import {assignCharacter,entropy,takeCard,trimHand,readySetup} from './scenario-tools.js';
export const blastSwordCard='a2-p10-r2c1';
export const blastSwordScenarios=['blast-sword-ordinary','blast-sword-owner-ordinary','blast-sword-ordinary-pair','blast-sword-owner-pair','blast-sword-low','blast-sword-owner-low','blast-sword-dedicated','blast-sword-pair','blast-sword-all','blast-sword-near','blast-sword-same-faction','blast-sword-water','blast-sword-metal','blast-sword-fort','blast-sword-maai-ordinary','blast-sword-maai-one-dedicated','blast-sword-maai-two-dedicated','blast-sword-evade-ordinary','blast-sword-evade-dedicated','blast-sword-fate-before','blast-sword-fate-after','blast-sword-suppressed','blast-sword-silenced','blast-sword-stopped','blast-sword-wrong-owner','blast-sword-decline','blast-sword-unprepared-ordinary','blast-sword-unprepared-dedicated','blast-sword-chant-ordinary','blast-sword-chant-dedicated','blast-sword-counter-ordinary','blast-sword-counter-dedicated','blast-sword-counter-unprepared','blast-sword-counter-decline','blast-sword-counter-fate','blast-sword-counter-maai-one','blast-sword-counter-maai-two','blast-sword-counter-water','blast-sword-counter-evade','blast-sword-counter-foreign'] as const;
export type BlastSwordScenario=typeof blastSwordScenarios[number];
export function isBlastSwordScenario(name:string):name is BlastSwordScenario{return (blastSwordScenarios as readonly string[]).includes(name);}
export function blastSwordMode(name:BlastSwordScenario){const suffix=name.replace('blast-sword-',''),incoming=suffix.startsWith('counter-'),dedicated=!['ordinary','owner-ordinary','ordinary-pair','owner-pair','low','owner-low','decline','unprepared-ordinary','chant-ordinary','fate-before','fate-after','maai-ordinary','evade-ordinary','counter-ordinary'].includes(suffix),owner=incoming&&suffix!=='counter-foreign'||dedicated&&!['wrong-owner','counter-foreign'].includes(suffix)||['owner-ordinary','owner-low','owner-pair'].includes(suffix),targets=suffix==='all'?[1,2,3]:['ordinary-pair','owner-pair','pair','maai-ordinary','maai-one-dedicated','maai-two-dedicated','evade-ordinary','evade-dedicated','suppressed','silenced'].includes(suffix)?[1,2]:[1],follower=suffix==='water'||suffix==='counter-water'?'a2-p23-r1c1':suffix==='metal'?'a2-p22-r1c1':suffix==='fort'?'a2-p19-r1c3':null,maai=suffix.includes('maai'),evade=suffix.includes('evade');return {suffix,dedicated,owner,targets,follower,maai,evade,incoming};}
/** Only initial deal/training is arranged. Followers, OPEN, statuses and preparation use accepted commands. */
export function makeBlastSwordPhysical(name:BlastSwordScenario,players:{id:string;name:string}[],options:{beforeStart?:boolean;prepared?:boolean;warrior?:number;spirit?:number;targetSpirit?:number}={}){
 const m=blastSwordMode(name),prior=['suppressed','stopped','silenced'].includes(m.suffix),incoming=m.incoming;let s=createGame(players,entropy(),{startingSeat:prior?3:m.suffix==='counter-unprepared'?1:0});const [a,b,c,d]=players.map(p=>p.id) as [string,string,string,string];
 for(const [i,p] of players.entries())assignCharacter(s,p.id,[m.owner?'侍大将のシン':'黒騎士ガーウィン','黒妖精のアーネス',m.suffix==='same-faction'?'大神官ジル':'魔導王ガイナス','聖騎士ランスロット'][i]!);
 for(const p of Object.values(s.players)){p.permanent={endurance:100,warrior_level:20,magic_level:20,spirit:20};p.permanent.spirit!+=(p.id===a?options.spirit??6:p.id===b?options.targetSpirit??11:p.id===c?12:6)-gameStats(s,p.id).spirit;}
 s.players[a]!.permanent!.warrior_level!+=(options.warrior??(['low','owner-low','fate-after'].includes(m.suffix)?7:m.dedicated?0:8))-gameStats(s,a).warrior_level;
 const keep=[takeCard(s,a,blastSwordCard),takeCard(s,d,'a2-p02-r2c3')];if(m.follower)keep.push(takeCard(s,b,m.follower));if(m.suffix==='near')keep.push(takeCard(s,a,'a2-p24-r1c3'));if(m.maai)keep.push(takeCard(s,b,'a2-p06-r1c3'),takeCard(s,b,'a2-p06-r2c1'));if(m.evade)keep.push(takeCard(s,b,'a2-p05-r3c1'));if(incoming)keep.push(takeCard(s,b,'a2-p24-r1c2'));if(prior)keep.push(takeCard(s,d,m.suffix==='suppressed'?'a2-p13-r1c2':m.suffix==='stopped'?'a2-p13-r2c1':'a2-p18-r1c1'));
 for(const p of players)trimHand(s,p.id,...keep);s.deck=[...s.deck.filter(id=>getAction(id)!.category!=='open'),...s.deck.filter(id=>getAction(id)!.category==='open')];s.events=[];
 function act(actorId:string,command:GameCommand,face=1){const input={actorId,command},e={...entropy(),dice:Array(100).fill(face)},r=transition(s,input,e);if(!r.ok)throw Error(`BLAST_SWORD_FIXTURE_${command.type}_${r.code}`);if(JSON.stringify(r)!==JSON.stringify(transition(JSON.parse(JSON.stringify(s)),input,e)))throw Error('BLAST_SWORD_FIXTURE_REPLAY');s=r.state;const ids=allCardInstanceIds(s);if(ids.length!==220||new Set(ids).size!==220)throw Error('BLAST_SWORD_FIXTURE_CARDS');}
 function settle(face=1){for(let n=0;n<600;n++){const w=s.windows?.at(-1);if(!w)return;act(w.participants[w.cursor]!,{type:'PASS'},face);}throw Error('BLAST_SWORD_FIXTURE_LIMIT');}
 for(const id of [a,b,c,d]){if(m.follower&&id===b)act(b,{type:'PLACE_INITIAL_FOLLOWER',cardInstanceId:m.follower});act(id,{type:'PASS_SETUP'});}readySetup(()=>s,id=>act(id,{type:'PASS_SETUP'}));if(options.beforeStart)return s;
 if(m.suffix==='counter-unprepared'){act(b,{type:'START_TURN'});act(b,{type:'CHOOSE_DRAW',draw:false});act(b,{type:'ATTACK',cardInstanceId:'a2-p24-r1c2',targetIds:[a],dedicated:false});for(let n=0;n<400;n++){const w=s.windows!.at(-1)!;if(w.kind==='normal-defense')return s;act(w.participants[w.cursor]!,{type:'PASS'});}throw Error('BLAST_SWORD_UNPREPARED_COUNTER');}
 if(prior){act(d,{type:'START_TURN'});settle();act(d,{type:'CHOOSE_DRAW',draw:false});act(d,{type:'ATTACK',cardInstanceId:m.suffix==='suppressed'?'a2-p13-r1c2':m.suffix==='stopped'?'a2-p13-r2c1':'a2-p18-r1c1',targetIds:[a],dedicated:false});settle(6);if(s.phase==='withdrawal')act(d,{type:'PASS_WITHDRAWAL'});act(d,{type:'END_TURN',discardIds:[]});settle();}
 act(a,{type:'START_TURN'});settle(prior?6:1);if(s.phase==='draw')act(a,{type:'CHOOSE_DRAW',draw:false});if(['stopped','decline'].includes(m.suffix)||m.suffix.startsWith('unprepared')||m.suffix.startsWith('chant-')||options.prepared===false)return s;
 act(a,{type:'CHANT',cardInstanceId:blastSwordCard,dedicated:['wrong-owner','counter-foreign'].includes(m.suffix)?false:m.dedicated});for(let n=0;n<250;n++){const id=s.seatOrder[s.turnSeat]!,w=s.windows?.at(-1);if(w)act(w.participants[w.cursor]!,{type:'PASS'},prior?6:1);else if(s.phase==='action'){if(id===a)break;if(incoming&&id===b){act(b,{type:'ATTACK',cardInstanceId:'a2-p24-r1c2',targetIds:[a],dedicated:false});for(let k=0;k<300;k++){if(s.windows?.at(-1)?.kind==='normal-defense')return s;const next=s.windows!.at(-1)!;act(next.participants[next.cursor]!,{type:'PASS'});}throw Error('BLAST_SWORD_INCOMING_LIMIT');}act(id,{type:'PASS_ACTION'});}else if(s.phase==='withdrawal')act(id,{type:'PASS_WITHDRAWAL'});else if(s.phase==='hand-adjustment')act(id,{type:'END_TURN',discardIds:s.players[id]!.hand.slice(gameStats(s,id).handLimit)});else if(s.phase==='turn-start')act(id,{type:'START_TURN'});else if(s.phase==='draw')act(id,{type:'CHOOSE_DRAW',draw:false});else throw Error('BLAST_SWORD_TURN');}
 if(m.suffix==='near'){act(a,{type:'APPROACH',cardInstanceId:'a2-p24-r1c3',targetId:b});settle();}if(m.suffix==='same-faction'){act(c,{type:'REVEAL_CHARACTER'});settle();}return s;
}
